"""Five applied coordinate problems closing chapter XI; the two positions in 1093 and printed erratum in 1097б."""
import argparse,json
from fractions import Fraction as F
from math import sqrt
from coordinate_additional_curves import entry,shape
from coordinate_additional_vectors import ROOT,BOOK
from circle_equations import equation_inputs

OUT=ROOT/'geometry-course/textbook/data/coordinate-additional-applications.json'


def triangle(d,base,height,label):
    V={'A':(0,0),'B':(base,0),'C':(d,height),'H':(d,0),'K':(base/2,0),'L':(d/2,height/2),'M':((base+d)/2,height/2)}
    return shape(label,{k:(x/4,y/4) for k,(x,y) in V.items()},edges=[('A','B'),('B','C'),('C','A'),('C','H'),('C','K'),('B','L'),('A','M')])


def two_positions():
    interior=triangle(8,28,15,'Основание высоты на отрезке AB')
    exterior=triangle(-8,28,15,'Основание высоты на продолжении AB')
    new=triangle(3,12,4,'Новые данные, основание высоты внутри')
    newout=triangle(-3,12,4,'Новые данные, основание высоты снаружи')
    reason='Пусть A=(0;0), B=(28;0), AC=17, высота к AB равна 15. Тогда C=(8;15) либо C=(−8;15), поскольку x²=17²−15²=64. Для C=(8;15) медианы из A, B, C равны 19,5; √2529/2; √261 см. Для C=(−8;15) в том же порядке получаем 12,5; √4321/2; √709 см. Отражение через AB длин не меняет.'
    c=entry(1093,None,'У треугольника известны стороны 17 и 28 см, а высота к стороне 28 см равна 15 см. Найди все возможные наборы длин трёх медиан. Каждому набору сопоставь собственный чертёж.',reason,
        'Высота может опускаться на продолжение основания. После вычисления горизонтального смещения длины 8 проверь оба знака.',
        [('Вычисли медианы для внутренней высоты','Пусть C=(8;15). Середины BC, AC, AB равны M=(18;7,5), L=(4;7,5), K=(14;0). Получаем AM=√(18²+7,5²)=19,5; BL=√(24²+7,5²)=√2529/2; CK=√(6²+15²)=√261 см.','Хотя рисунок не обязан быть в сантиметрах, расстояния считай в выбранных координатах.'),
         ('Проверь внешнюю высоту','Для C=(−8;15) получаются M=(10;7,5), L=(−4;7,5), K=(14;0). Тогда AM=12,5, BL=√(32²+7,5²)=√4321/2, CK=√(22²+15²)=√709 см. Другой знак у ординаты только отражает одну из этих фигур.','Оба значения горизонтальной координаты соответствуют исходным длинам.'),
         ('Измени данные','Пусть AB=12, AC=5, высота 4. Тогда xC=±3. Середина AB равна K=(6;0). При xC=3 медиана CK=5, при xC=−3 медиана CK=√97. Остальные медианы также строятся к серединам своих сторон.','При разных положениях высоты сравни одну и ту же медиану.')],[interior,exterior,new,newout],
        [('Чему равен квадрат медианы из C при внешней высоте в исходном треугольнике?','709','По горизонтали от −8 до 14 имеем 22, по вертикали 15.'),('Каков квадрат медианы из C при внешней высоте в новом треугольнике?','97','Вычисли (6−(−3))²+4².')],(96,))
    caption='Одна клетка — 4 см. K, L, M — середины AB, AC и BC, H — основание высоты.';c['visualization']['caption']=caption;c['visualization']['model']['description']=caption
    return c


def trapezoid():
    def view(label,d,b,t,h):
        pts={'A':(0,0),'D':(d,0),'B':(t,h),'C':(t+b,h),'M':((t+b)/2,h/2),'N':((t+d)/2,h/2)}
        return shape(label,pts,edges=[('A','B'),('B','C'),('C','D'),('D','A'),('A','C'),('B','D'),('M','N')])
    c=entry(1094,None,'Докажи, что отрезок между серединами диагоналей трапеции равен половине разности длин её оснований.', 'Выбери A=(0;0), D=(d;0), B=(t;h), C=(t+b;h), где d≥b>0. Точки M и N, середины AC и BD, имеют одну ординату h/2. Их абсциссы (t+b)/2 и (t+d)/2, значит MN=(d−b)/2. При другом порядке длин та же запись с модулем разности.',
        'Положи ось Ox вдоль большего основания. Сдвиг второго основания на t должен исчезнуть из ответа.',
        [('Построй конкретную трапецию','При d=10, b=4, t=2, h=4 точки M=(3;2) и N=(6;2) лежат на горизонтали. Расстояние MN=3, половина разности 10−4.','Соединяются середины диагоналей, а не середины боковых сторон.'),
         ('Выведи формулу в буквах','У M абсцисса (t+b)/2, у N — (t+d)/2. Вычти: MN=|(t+d−t−b)/2|=|d−b|/2, поскольку обе ординаты h/2. Ни высота, ни сдвиг верхнего основания не влияют на длину.','В формулу входит разность оснований; у средней линии, напротив, была бы полусумма.'),
         ('Проверь сдвинутый верх','При d=8, b=6, t=−2, h=6 получаем M=(2;3), N=(3;3). Длина равна 1. Половина разности 8−6 совпадает с этим значением.','Выход верхней вершины за вертикаль через A не мешает доказательству.')],
        [view('Середины диагоналей',10,4,2,4),view('Та же разность при другом сдвиге',10,4,4,5),view('Новые основания и сдвиг влево',8,6,-2,6)],
        [('Чему равна длина MN для оснований 10 и 4?','3','Половина разности, а не суммы.'),('Какова длина MN для новых оснований 8 и 6?','1','Вычти 6 из 8 и раздели на 2.')],(96,))
    return c


def parallelogram():
    def view(label,a,b,m):
        pts={'A':a,'C':(-a[0],-a[1]),'B':b,'D':(-b[0],-b[1]),'M':m}
        return shape(label,pts,edges=[('A','B'),('B','C'),('C','D'),('D','A'),('M','A'),('M','B'),('M','C'),('M','D')])
    return entry(1095,None,'В параллелограмме ABCD точка M может быть любой точкой плоскости. Докажи, что (AM²+CM²)−(BM²+DM²) от положения M не зависит.',
        'Возьми пересечение диагоналей O началом координат. Если A=(u;v), C=(−u;−v), B=(p;q), D=(−p;−q), M=(x;y), то AM²+CM²=2(x²+y²)+2(u²+v²). Для второй пары получается 2(x²+y²)+2(p²+q²). Разность равна 2(OA²−OB²)=(AC²−BD²)/2, величине, определяемой только параллелограммом.',
        'Противоположные вершины симметричны относительно точки пересечения диагоналей. При сложении квадратов их перекрёстные слагаемые уничтожаются.',
        [('Вычисли для двух точек','Пусть A=(3;1), C=(−3;−1), B=(1;2), D=(−1;−2). Для M=(1;0) сумма по паре A,C равна 5+17=22, по паре B,D — 4+8=12. Разность равна 10.','Меняется каждая сумма, но нас интересует их разность.'),
         ('Докажи независимость','В сумме (x−u)²+(x+u)² исчезают члены с xu, остаётся 2x²+2u². Аналогично по y. При вычитании сумм для двух диагоналей уничтожаются также 2x²+2y². В показанном параллелограмме постоянная 2(10−5)=10, в том числе для внешней M.','Любая точка плоскости имеет пару (x;y), поэтому область внутри фигуры не ограничивает доказательство.'),
         ('Проверь другой параллелограмм','Теперь A=(2;0), C=(−2;0), B=(0;3), D=(0;−3). Постоянная равна 2(4−9)=−10. Выбери M=(3;1); сумма квадратов до A,C равна 2+26=28, а до B,D — 13+25=38.','Постоянная может быть отрицательной и зависит от выбора порядка пар.')],
        [view('Внутренняя точка M',(3,1),(1,2),(1,0)),view('Другая точка того же параллелограмма',(3,1),(1,2),(5,2)),view('Новый параллелограмм',(2,0),(0,3),(3,1))],
        [('Чему равна разность двух сумм на первом рисунке?','10','Вычти 12 из 22.'),('Чему равна разность для нового параллелограмма?','-10','Используй порядок (A,C) минус (B,D).')],(96,))


def median_formula():
    def view(label,pts,edges):
        return shape(label,pts,edges=[('A','B'),('B','C'),('C','A'),*edges])
    pts={'A':(2,4),'B':(-3,0),'C':(3,0),'H':(0,0)}
    new={'A':(-3,0),'B':(3,0),'C':(0,4),'U':(1.5,2),'V':(-1.5,2)}
    return entry(1096,None,'Выведи формулу длины медианы из A через стороны треугольника. Используя её, докажи, что при двух равных медианах треугольник равнобедренный.',
        'Пусть a=BC, b=CA, c=AB. Тогда mₐ²=(2b²+2c²−a²)/4 и mₐ=√(2b²+2c²−a²)/2. Аналогично mᵦ²=(2c²+2a²−b²)/4. Из mₐ=mᵦ следует 3b²=3a², а положительность длин даёт a=b. Для другой пары медиан рассуждение получается заменой букв.',
        'Положи начало в середину BC и направь ось Ox вдоль BC. Сумма AB² и AC² избавит от произведения переменной на a.',
        [('Запиши координаты','Возьми B=(−a/2;0), C=(a/2;0), A=(x;y). Квадрат медианы AH равен x²+y². Сумма c²+b²=(x+a/2)²+y²+(x−a/2)²+y²=2(x²+y²)+a²/2.','Середина стороны позволяет выбрать симметричные абсциссы концов.'),
         ('Получи длину и используй равенство','После преобразования 4mₐ²=2b²+2c²−a². Корень из обеих частей даёт формулу. Для равных mₐ и mᵦ приравняй 2b²+2c²−a² и 2a²+2c²−b². После сокращения получаем a=b. В примере B=(−3;0), C=(3;0), A=(2;4) проверка даёт 4AH²=80.','Квадратный корень выбирается неотрицательным, потому что медиана имеет длину.'),
         ('Проверь на равнобедренном треугольнике','Пусть A=(−3;0), B=(3;0), C=(0;4). CA=CB=5. Середины U=(1,5;2) стороны BC и V=(−1,5;2) стороны AC дают AU²=BV²=97/4. Равны медианы именно из A и B.','Соотнеси каждую медиану с противоположной ей стороной.')],
        [view('Медиана к горизонтальному основанию',pts,[('A','H')]),view('Длины медианы и боковых сторон',pts,[('A','H'),('B','H'),('H','C')]),view('Две равные медианы',new,[('A','U'),('B','V')])],
        [('Каков квадрат AH в числовом примере A=(2;4)?','20','Сложи 2² и 4².'),('Чему равно 4AU² в новом равнобедренном треугольнике?','97','Для AU смещение (9/2;2); умножь сумму квадратов на 4.')],(96,))

def recovered_loci(part):
    # A and B are distinct in the school problem. The ratio form uses a=AB>0.
    if part=='а':
        def view(a,title):
            return shape(title,{'A':(0,0),'B':(a,0),'M':(-a,2*a)},edges=[('A','B'),('A','M'),('B','M'),('S','M')],circles=[('S',(-a,0),4*a*a)])
        initial=shape('Отражение B относительно A',{'A':(0,0),'B':(2,0),'S':(-2,0)},edges=[('S','B')])
        correct=view(2,'Проверка исходного места точек');fresh=view(3,'Новая длина AB и новый радиус')
        why='Введи A=(0;0), B=(a;0), a=AB. Равенство 2AM²−BM²=2a² даёт x²+y²+2ax−3a²=0, то есть (x+a)²+y²=4a². Это окружность радиуса 2a с центром S=(−a;0), отражением B относительно A. Все переходы равносильны, поэтому любая точка этой окружности подходит.'
        c=entry(1097,part,'Даны различные точки A и B. Найди все M, для которых 2AM²−BM²=2AB². Укажи положение центра относительно отрезка AB и радиус.',why,'Положи ось Ox вдоль луча AB. Знак перед BM² меняет линейный член после раскрытия скобок.',
            [('Составь уравнение','Для A=(0;0), B=(a;0), M=(x;y) имеем AM²=x²+y² и BM²=(x−a)²+y². После вычитания остаётся x²+y²+2ax−3a²=0.','Координата x может быть и отрицательной.'),
             ('Выдели квадрат и проверь обратный переход','Переносим к квадрату x²+2ax+a², получаем (x+a)²+y²=4a². Центр находится на продолжении BA за A. При a=2 точка M=(−2;4) даёт AM²=20, BM²=32 и 2·20−32=8=2AB². Раскрытие квадратов возвращает исходное условие для любой точки окружности.','Разность задаёт всю окружность, а не только проверенную точку.'),
             ('Измени расстояние между заданными точками','Для a=3 центр S=(−3;0), радиус 6. У верхней точки M=(−3;6) квадраты AM²=45, BM²=72 дают 2·45−72=18=2·9.','Положение центра и радиус масштабируются вместе с AB.')],
            [initial,correct,fresh],[('При AB=2 какую абсциссу имеет центр?','-2','Центр — отражение B относительно A.'),('Каков радиус при новой длине AB=3?','6','Удвой AB.')])
        c['answer']=dict(mode='exact',accepted=['-1;2','-1; 2','(-1;2)','(-1; 2)'],prompt='При A=(0;0), B=(a;0) введи xS/a и R/a через точку с запятой.',feedback='Центр расположен по другую сторону от A относительно B, поэтому его абсцисса отрицательна. Радиус равен 2a.')
        return c
    def actual(a,title,m):
        return shape(title,{'A':(0,0),'B':(a,0),'M':m},edges=[('A','M'),('B','M'),('S','M')],circles=[('S',(a/2,0),5*a*a/4)])
    actual2=actual(2,'По условию с двумя коэффициентами 2',(0,2))
    actual4=actual(4,'Та же задача при AB=4',(0,4))
    key=shape('Проверка ответа на с. 399: только его окружность',{'A':(0,0),'B':(2,0),'P':(4,0)},edges=[('A','P'),('K','P')],circles=[('K',(F(4,3),0),F(64,9))])
    bare=shape('A и B на оси, проверяемая точка M',{'A':(0,0),'B':(2,0),'M':(0,2)},edges=[('A','M'),('B','M')])
    answer='По напечатанному условию центр S — середина AB, радиус R=√5·AB/2. При A=(0;0), B=(a;0) уравнение: (x−a/2)²+y²=5a²/4. Подстановка любого его решения даёт 2AM²+2BM²=6a². На с. 399 напечатаны центр на расстоянии 2AB/3 от A и радиус 4AB/3; эти значения удовлетворяют иному условию, AM²+2BM²=6AB².'
    c=entry(1097,'б','На с. 270 требуется найти точки M при 2AM²+2BM²=6AB². В ответах на с. 399 указан другой центр. Выведи окружность по условию на с. 270, затем проверь оба описания подстановкой.',answer,
        'Сначала раздели все слагаемые исходного равенства на 2. Равные коэффициенты у двух квадратов подсказывают симметрию при перестановке A и B.',
        [('Собери уравнение','Пусть A=(0;0), B=(a;0). После деления на 2 получаем AM²+BM²=3a². Раскрываем квадраты: 2x²−2ax+a²+2y²=3a². Получается x²−ax+y²=a².','Оба коэффициента 2 перед квадратами расстояний присутствуют в напечатанном условии.'),
         ('Определи место точек и проверь ответ книги','Выделяя квадрат, получаем (x−a/2)²+y²=5a²/4. Все преобразования обратимы. При a=2 для M=(0;2) имеем 2·4+2·8=24. В напечатанном ответе другая окружность, с центром (4/3;0) и радиусом 8/3. Точка P=(4;0) лежит на ней, но 2·16+2·4=40, тогда как 6AB²=24.','Проверь точку одновременно по фигуре и по исходному условию; совпадения одного коэффициента недостаточно.'),
         ('Повтори с другими данными','Пусть a=4. У правильной окружности S=(2;0), R²=20. В точке M=(0;4) получаем AM²=16, BM²=32, а 2·16+2·32=96=6·16. Для сравнения, окружность из ответов получается именно при AM²+2BM²=6a²: выделение квадрата даёт (x−2a/3)²+y²=16a²/9.','Значения центра и радиуса определяет конкретное равенство; в ответе этой задачи сохраняем оба начальных множителя.')],
        [bare,actual2,actual4,key],[('При AB=2 какую абсциссу имеет центр окружности из условия?','1','Середина точек с абсциссами 0 и 2 имеет абсциссу 1.'),('При AB=4 чему равен квадрат правильного радиуса?','20','Вычисли 5·4²/4.')])
    c['answer']=dict(mode='exact',prompt='При A=(0;0), B=(a;0) введи xS/a и R²/a² через точку с запятой. Укажи результат для условия на с. 270.',accepted=['1/2;5/4','1/2; 5/4','½;5/4','½; 5/4','0,5;1,25','0,5; 1,25','0.5;1.25','0.5; 1.25'],feedback='В условии оба квадрата имеют коэффициент 2. Приведи равенство к (x−a/2)²+y²=5a²/4. Указываются координата центра и именно квадрат радиуса в долях a².')
    c['review']['reviewer']+=' №1097б: расхождение условия на с. 270 и ответа на с. 399 независимо проверено преобразованием, симметрией и контрольными точками.'
    return c


def build():return {'bookId':BOOK,'lessons':[two_positions(),trapezoid(),parallelogram(),median_formula(),recovered_loci('а'),recovered_loci('б')]}


if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');opts=parser.parse_args();data=json.dumps(build(),ensure_ascii=False,separators=(',',':'))+'\n'
    if opts.check:assert OUT.read_text()==data
    else:OUT.write_text(data)
